  const rangePicker = document.querySelector('.ant-picker-range');
  const startInput = document.querySelector('input[date-range="start"]');
  const endInput = document.querySelector('input[placeholder="End date"]');

  // Check React props or fiber
  const getFiber = (el) => {
    for (const k in el) {
      if (k.startsWith('__reactFiber') || k.startsWith('__reactInternalInstance')) {
        return el[k];
      }
    }
    return null;
  };

  const startFiber = getFiber(startInput);

  return {
    startVal: startInput?.value,
    endVal: endInput?.value,
    hasFiber: !!startFiber,
    clearBtn: !!document.querySelector('.ant-picker-clear')
  };
});
