const tabId = 248688717;
const tableData = await browserjs(tabId, () => {
  const table = document.querySelector('table');
  if (!table) return { error: "No table found" };

  const headers = Array.from(table.querySelectorAll('thead tr')).map(tr => 
    Array.from(tr.querySelectorAll('th')).map(th => th.textContent.replace(/\s+/g, ' ').trim())
  );

  const rows = Array.from(table.querySelectorAll('tbody tr')).map(tr => 
    Array.from(tr.querySelectorAll('td')).map(td => td.textContent.replace(/\s+/g, ' ').trim())
  );

  return { headers, rows };
});
console.log("Headers:", JSON.stringify(tableData.headers, null, 2));
console.log("Rows count:", tableData.rows?.length);
